    function buildChart() {
      if (typeof Chart === 'undefined') { console.error('Chart.js not loaded'); return; }
      var isDark = document.documentElement.classList.contains('theme-dark');
      var axisText = isDark ? '#EDEDED' : '#111827';
      var axisMuted = isDark ? 'rgba(237,237,237,0.65)' : 'rgba(17,24,39,0.60)';
      var grid = isDark ? 'rgba(255,255,255,0.08)' : 'rgba(0,0,0,0.08)';

      var baseColor = isDark ? 'rgba(237,237,237,0.22)' : 'rgba(17,24,39,0.20)';
      var baseColorStrong = isDark ? 'rgba(237,237,237,0.34)' : 'rgba(17,24,39,0.32)';

      var palette = {
        China: '#DC2626',
        Japan: '#7C3AED',
        India: '#059669'
      };

      var datasets = source.data.map(function(row) {
        var name = row.country;
        var isHighlight = (name === 'China' || name === 'Japan' || name === 'India');

        var points = years.map(function(y) { return { x: y, y: row[y] }; });

        var color = isHighlight ? palette[name] : baseColor;
        var width = isHighlight ? (name === 'China' ? 5 : 4) : 1.5;
        var alpha = isHighlight ? 1 : 1;

        return {
          label: name,
          data: points,
          borderColor: color,
          backgroundColor: color,
          borderWidth: width,
          pointRadius: isHighlight ? 4 : 2.2,
          pointHoverRadius: isHighlight ? 6 : 4,
          pointBorderWidth: 0,
          pointBackgroundColor: color,
          tension: 0.32,
          fill: false,
          spanGaps: true,
          order: isHighlight ? 0 : 10,
          hidden: false
        };
      });

      // Make the non-highlight set a bit more legible (still subtle)
      datasets.forEach(function(ds) {
        if (ds.label !== 'China' && ds.label !== 'Japan' && ds.label !== 'India') {
          ds.borderColor = baseColor;
          ds.backgroundColor = baseColor;
          ds.pointBackgroundColor = baseColorStrong;
        }
      });

      ChartManager.safeInit('bumpChart', {
        type: 'line',
        data: { labels: years, datasets: datasets },
        options: {
          responsive: true,
          maintainAspectRatio: false,
          interaction: { mode: 'nearest', intersect: false },
          plugins: {
            tooltip: {
              enabled: true,
              callbacks: {
                title: function(items) {
                  return items && items[0] ? ('Year: ' + items[0].label) : '';
                },
                label: function(ctx) {
                  return ctx.dataset.label + ': Rank ' + ctx.parsed.y;
                }
              }
            },
            legend: {
              position: 'bottom',
              labels: {
                color: axisMuted,
                boxWidth: 14,
                boxHeight: 3,
                usePointStyle: true,
                pointStyle: 'line',
                filter: function(item) {
                  // Only show highlights in legend; the pill legend explains others.
                  return (item.text === 'China' || item.text === 'Japan' || item.text === 'India');
                }
              }
            },
            title: {
              display: true,
              text: 'GDP rank over time (lower is better)',
              color: axisText,
              font: { weight: '600', size: 14 },
              padding: { top: 6, bottom: 14 }
            }
          },
          scales: {
            x: {
              type: 'category',
              title: { display: true, text: 'Year', color: axisMuted, font: { weight: '600' } },
              ticks: { color: axisText },
              grid: { color: grid }
            },
            y: {
              min: 1,
              max: 15,
              reverse: true,
              title: { display: true, text: 'GDP rank (1 = highest GDP)', color: axisMuted, font: { weight: '600' } },
              ticks: {
                color: axisText,
                stepSize: 1,
                callback: function(value) { return value; }
              },
              grid: { color: grid }
            }
          }
        }
      });
    }

    function onThemeChange() { buildChart(); }
    window.addEventListener('load', buildChart);

    async function downloadImage() {
      var menu = document.querySelector('.viz-menu');
      if (menu) menu.style.display = 'none';
      try {
        var url = await htmlToImage.toPng(document.body, {
          quality: 1,
          pixelRatio: 2,
          filter: function(n) { return !n.classList || !n.classList.contains('viz-menu'); }
        });
        var a = document.createElement('a');
        a.href = url;
        a.download = document.title.replace(/\s+/g, '-').toLowerCase() + '.png';
        a.click();
      } catch (e) {
        console.error('Download failed:', e);
      }
      if (menu) menu.style.display = '';
    }
